import heapq


def mergeDistinct(rows):
    h = [(r[0], i, 0) for i, r in enumerate(rows) if r]
    heapq.heapify(h)
    out = []
    while h:
        v, i, j = heapq.heappop(h)
        if not out or out[-1] != v:
            out.append(v)
        if j + 1 < len(rows[i]):
            heapq.heappush(h, (rows[i][j + 1], i, j + 1))
    return out
